#!/usr/bin/env python3
"""Writes MagicSquareOfSquares/CoverDescentTable.lean: certificates for the descent of CoverDescent.lean.

For each pair (m, n) of G1.exceptions1000 (read from G1Census1000.lean) with m^2 + n^2 neither a square nor twice a
square, the candidates are the products d of the primes of 2 m n (m^2 - n^2).  For a modulus M = p^k from a fixed list
(the prime powers up to 128), the program finds the candidates that are excluded modulo M by the check `kills` of
CoverDescent.lean, which it mirrors: at every point (1, v), and (u, 1) with p | u, of the projective line modulo M, the
four forms are not all squares modulo M, or d times one of the eight products of the four linear forms (with
conjugates) is not the square of a Gaussian integer modulo M.  A ratio gets an entry when every candidate is excluded by
some modulus.  The Lean kernel then checks every entry again; this program is not trusted.
usage (from the root of the repository): python3 scripts/cover_descent/lean_cert.py [--check]"""
import sys, re, itertools
from math import isqrt
FLAGS = list(itertools.product((0, 1), repeat=3))
def gmul(p, q): return (p[0]*q[0] - p[1]*q[1], p[0]*q[1] + p[1]*q[0])
def cj(p): return (p[0], -p[1])
def forms(m, n, u, v): return [(m*v, n*u), (n*v, m*u), ((m+n)*(u-v), (m-n)*(u+v)), ((m-n)*(u-v), (m+n)*(u+v))]
def Q(P, f):
    r = gmul(P[0], cj(P[1]) if f[0] else P[1]); r = gmul(r, cj(P[2]) if f[1] else P[2]); return gmul(r, cj(P[3]) if f[2] else P[3])
MASK = {}
def masks(M):
    if M not in MASK:
        MASK[M] = (set(w*w % M for w in range(M)), set(((a*a - b*b) % M, (2*a*b) % M) for a in range(M) for b in range(M)))
    return MASK[M]
def survivors(m, n, M, p):
    sq, g = masks(M); out = []
    for u, v in [(1, v) for v in range(M)] + [(u, 1) for u in range(0, M, p)]:
        P = forms(m, n, u, v)
        if all((z[0]*z[0] + z[1]*z[1]) % M in sq for z in P): out.append([Q(P, f) for f in FLAGS])
    return out
def killed(d, surv, M):
    g = masks(M)[1]
    return not any(all(((d*X) % M, (d*Y) % M) in g for X, Y in pr) for pr in surv)
def factor(x):
    out = set(); q = 2
    while q*q <= x:
        while x % q == 0: out.add(q); x //= q
        q += 1
    if x > 1: out.add(x)
    return out
CAP = 128
PR = [q for q in range(5, CAP) if all(q % r for r in range(2, int(q**0.5) + 1))]
MODS = [(2, 3), (3, 2)] + sorted([(q, 1) for q in PR] + [(2, 4), (5, 2), (3, 3), (2, 5), (7, 2), (2, 6), (3, 4), (11, 2), (5, 3), (2, 7)], key=lambda t: t[0]**t[1])
def one(mn):
    m, n = mn
    P = sorted(factor(2*m*n*(m*m - n*n))); cands = [1]
    for q in P: cands = cands + [c*q for c in cands]
    left = set(cands); cert = []
    for p, k in MODS:
        M = p**k; surv = survivors(m, n, M, p)
        kl = sorted(d for d in left if killed(d, surv, M))
        if kl: cert.append((p, k, kl)); left -= set(kl)
        if not left: break
    return dict(m=m, n=n, primes=P, cands=len(cands), cert=cert, left=sorted(left))
def smask(M):
    S = 0
    for r in range(M): S |= 1 << (r*r % M)
    return S
def gmask(M):
    G = 0
    for a in range(M):
        for b in range(M): G |= 1 << (M*((a*a - b*b) % M) + (2*a*b) % M)
    return G
def prods(ps):                                              # the order of `prods` in CoverDescent.lean
    if not ps: return [1]
    r = prods(ps[1:]); return r + [ps[0]*x for x in r]
def cmask(ps, ds):
    pos = {d: i for i, d in enumerate(prods(ps))}; c = 0
    for d in ds: c |= 1 << pos[d]
    return c
HEAD = 'import MagicSquareOfSquares.CoverDescent\nimport MagicSquareOfSquares.G1Census1000\n\n/-!\n# Certificates for the descent of `CoverDescent.lean`\n\nGenerated by `scripts/cover_descent/lean_cert.py`; do not edit by hand.\n\n* `masks`: for each modulus used, the squares and the Gaussian squares modulo it, as bit masks;\n  `mask8`, …: each mask is the one computed by `sMask`, `gMask` (evaluated by the kernel).\n* `table`: for each ratio `m : n`, the primes of `2mn(m − n)(m + n)` and a certificate: lines\n  `(p, k, c)` saying that modulo `p^k` the candidates at the bits of `c` are excluded.\n  `table_ok`: every entry passes `entryOk` (evaluated by the kernel, in pieces `chunk0`, …).\n* `no_fullSquares_of_mem_ratios`: for the ratios of the table, no rational `t` makes the five\n  free cells of the G1 family squares.\n* `IsMSS.ratio_ne_of_coverDescent`, `IsMSS.ratio_ne_of_le_1000_descent`: the same for a magic\n  square of squares; with the census by residue classes, for coprime `1 ≤ n < m ≤ 1000` the ratio\n  is one of the pairs of `exceptions`.\n\nNo `native_decide`: every check is `decide +kernel`.\n-/\n\nset_option Elab.async false\n\nnamespace MagicSquareOfSquares.CoverDescent\n\n'
TAIL = "\n/-- **No solution of the five-form system, from a certificate.** -/\ntheorem no_fullSquares_of_entry {masks : List (ℕ × ℕ × ℕ)} (hmasks : MasksOk masks)\n    {e : ℕ × ℕ × List ℕ × List (ℕ × ℕ × ℕ)} (he : entryOk masks e = true) (t : ℚ) :\n    ¬G1.FullSquares e.1 e.2.1 t := by\n  intro h\n  obtain ⟨u, V, hV, hcop, h0, _, h8, hL, hU⟩ := G1.exists_coprime_squares_full h\n  have hv : (V : ℤ) ≠ 0 := by exact_mod_cast hV.ne'\n  have huv : (u : ℤ) + V ≠ 0 := by\n    have : (0 : ℤ) < (u : ℤ) + V := by positivity\n    exact this.ne'\n  refine no_point_of_entry hmasks he (Nat.isCoprime_iff_coprime.mpr hcop) hv huv ?_ ?_ ?_ ?_\n  · obtain ⟨r, hr⟩ := h0\n    exact ⟨r, by dsimp only [nrm, P0]; linear_combination hr⟩\n  · obtain ⟨r, hr⟩ := h8\n    exact ⟨r, by dsimp only [nrm, P8]; linear_combination hr⟩\n  · obtain ⟨r, hr⟩ := hL\n    exact ⟨r, by dsimp only [nrm, PL]; linear_combination hr⟩\n  · obtain ⟨r, hr⟩ := hU\n    exact ⟨r, by dsimp only [nrm, PU]; linear_combination hr⟩\n\n/-- **For the ratios of the table, no rational `t` makes the five free cells of the G1 family\nsquares.** Among them are `820 : 799` and `889 : 320`. -/\ntheorem no_fullSquares_of_mem_ratios {m n : ℕ} (h : (m, n) ∈ ratios) (t : ℚ) :\n    ¬G1.FullSquares m n t := by\n  rw [← ratios_eq, List.mem_map] at h\n  obtain ⟨e, he, heq⟩ := h\n  have h1 : entryOk masks e = true := (List.all_eq_true.mp table_ok) e he\n  have h2 := no_fullSquares_of_entry masks_ok h1 t\n  rw [Prod.mk.injEq] at heq\n  rw [← heq.1, ← heq.2]\n  exact h2\n\n/-- The pairs of `G1.exceptions1000` that are not in the table. -/\ndef exceptions : List (ℕ × ℕ) := G1.exceptions1000.filter fun x => decide (x ∉ ratios)\n\ntheorem exceptions_length : exceptions.length = EXCEPTIONS_LEFT := by decide +kernel\n\nend MagicSquareOfSquares.CoverDescent\n\nnamespace MagicSquareOfSquares\n\n/-- **In a 3×3 magic square of squares the ratio `(b + d) : (h + f)` of the edge roots is not one\nof the ratios of the table of `CoverDescent`.** -/\ntheorem IsMSS.ratio_ne_of_coverDescent {a b c d e f g h i T : ℤ} (hs : IsMSS a b c d e f g h i T)\n    {m n : ℕ} (hn0 : 0 < n) (hmem : (m, n) ∈ CoverDescent.ratios) (hne : h + f ≠ 0) (hbd : b ≠ d) :\n    (b + d) * n ≠ (h + f) * m :=\n  fun hmn => CoverDescent.no_fullSquares_of_mem_ratios hmem _ (hs.fullSquares hn0 hmn hne hbd)\n\n/-- **In a 3×3 magic square of squares the ratio `(b + d) : (h + f)` of the edge roots is not\n`m : n` for any coprime `1 ≤ n < m ≤ 1000` outside the pairs of `CoverDescent.exceptions`.** -/\ntheorem IsMSS.ratio_ne_of_le_1000_descent {a b c d e f g h i T : ℤ}\n    (hs : IsMSS a b c d e f g h i T) {m n : ℕ} (hn0 : 0 < n) (hnm : n < m) (hm : m ≤ 1000)\n    (hcop : Nat.Coprime m n) (hex : (m, n) ∉ CoverDescent.exceptions) (hne : h + f ≠ 0)\n    (hbd : b ≠ d) : (b + d) * n ≠ (h + f) * m := by\n  by_cases hr : (m, n) ∈ CoverDescent.ratios\n  · exact hs.ratio_ne_of_coverDescent hn0 hr hne hbd\n  · refine hs.ratio_ne_of_le_1000 hn0 hnm hm hcop ?_ hne hbd\n    intro hmem\n    apply hex\n    unfold CoverDescent.exceptions\n    rw [List.mem_filter]\n    exact ⟨hmem, decide_eq_true hr⟩\n\nend MagicSquareOfSquares\n"
if __name__ == '__main__':
    src = open('MagicSquareOfSquares/G1Census1000.lean').read()
    body = src[src.index('def exceptions1000'):]; body = body[:body.index(']')]
    pairs = [tuple(int(x) for x in t) for t in re.findall(r'\((\d+), (\d+)\)', body)]
    def triv(m, n):
        S = m*m + n*n; return isqrt(S)**2 == S or (S % 2 == 0 and isqrt(S//2)**2 == S//2)
    res = [one(p) for p in pairs if not triv(*p)]
    ok = [r for r in res if not r['left']]
    mods = sorted(set(p**k for r in ok for p, k, _ in r['cert']))
    out = []
    for M in mods:
        out += ['def S%d : ℕ := 0x%x' % (M, smask(M)), 'def G%d : ℕ := 0x%x' % (M, gmask(M)),
                'theorem mask%d : S%d = sMask %d ∧ G%d = gMask %d := by decide +kernel' % (M, M, M, M, M), '']
    out += ['/-- The masks of the moduli used: `(M, squares modulo M, Gaussian squares modulo M)`. -/',
            'def masks : List (ℕ × ℕ × ℕ) := [' + ', '.join('(%d, S%d, G%d)' % (M, M, M) for M in mods) + ']', '',
            'theorem masks_ok : MasksOk masks := by\n  intro e he\n  simp only [masks, List.mem_cons, List.not_mem_nil, or_false] at he\n  rcases he with ' + ' | '.join('rfl' for M in mods) + '\n' + ''.join('  · exact mask%d\n' % M for M in mods), '']
    CH = 8; chunks = [ok[i:i + CH] for i in range(0, len(ok), CH)]
    for j, ch in enumerate(chunks):
        out.append('def chunk%d : List (ℕ × ℕ × List ℕ × List (ℕ × ℕ × ℕ)) := [\n' % j + ',\n'.join(
            '  (%d, %d, %s, [%s])' % (r['m'], r['n'], r['primes'], ', '.join('(%d, %d, 0x%x)' % (p, k, cmask(r['primes'], ds)) for p, k, ds in r['cert'])) for r in ch) + ']')
        out.append(''); out.append('theorem chunk%d_ok : chunk%d.all (entryOk masks) = true := by decide +kernel' % (j, j)); out.append('')
    out.append('/-- The table: `(m, n, primes, certificate)` for %d ratios. -/' % len(ok))
    out.append('def table : List (ℕ × ℕ × List ℕ × List (ℕ × ℕ × ℕ)) :=\n  ' + ' ++ ('.join('chunk%d' % j for j in range(len(chunks))) + ')'*(len(chunks) - 1)); out.append('')
    out.append('theorem table_ok : table.all (entryOk masks) = true := by\n  unfold table\n' + ''.join('  rw [List.all_append, chunk%d_ok, Bool.true_and]\n' % j for j in range(len(chunks) - 1)) + '  exact chunk%d_ok' % (len(chunks) - 1)); out.append('')
    out.append('/-- The ratios of the table. -/\ndef ratios : List (ℕ × ℕ) := [' + ', '.join('(%d, %d)' % (r['m'], r['n']) for r in ok) + ']'); out.append('')
    out.append('theorem ratios_eq : table.map (fun e => (e.1, e.2.1)) = ratios := by decide +kernel'); out.append('')
    text = HEAD + '\n'.join(out) + TAIL.replace('EXCEPTIONS_LEFT', str(len(pairs) - len(ok)))
    if '--check' in sys.argv:
        same = open('MagicSquareOfSquares/CoverDescentTable.lean').read() == text
        print('CoverDescentTable.lean is the output of this program: %s' % same); sys.exit(0 if same else 1)
    open('MagicSquareOfSquares/CoverDescentTable.lean', 'w').write(text)
    print('pairs of exceptions1000: %d; not of the two exceptional types: %d; with a certificate: %d; moduli: %s' % (len(pairs), len(res), len(ok), mods))
    print('without a certificate (moduli up to %d): %s' % (CAP, [(r['m'], r['n']) for r in res if r['left']]))
